import java.util.*;
import java.math.*;

public class Main {
    static String to_string(String s) {
        return "\"" + s + "\"";
    }

    static String to_string(char[] s) {
        return to_string(new String(s));
    }

    static String to_string(boolean b) {
        return b ? "true" : "false";
    }

    static String to_string(List<Boolean> v) {
        StringBuilder res = new StringBuilder("{");
        boolean first = true;
        for (Boolean b : v) {
            if (!first) res.append(", ");
            first = false;
            res.append(to_string(b));
        }
        res.append("}");
        return res.toString();
    }

    static String to_string(BitSet v, int N) {
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < N; i++) {
            res.append(v.get(i) ? '1' : '0');
        }
        return res.toString();
    }

    static <T> String to_string(Collection<T> v) {
        StringBuilder res = new StringBuilder("{");
        boolean first = true;
        for (T x : v) {
            if (!first) res.append(", ");
            first = false;
            res.append(to_string(x));
        }
        res.append("}");
        return res.toString();
    }

    static <A, B> String to_string(Pair<A, B> p) {
        return "(" + to_string(p.first) + ", " + to_string(p.second) + ")";
    }

    static <A, B, C> String to_string(Tuple3<A, B, C> p) {
        return "(" + to_string(p.first) + ", " + to_string(p.second) + ", " + to_string(p.third) + ")";
    }

    static <A, B, C, D> String to_string(Tuple4<A, B, C, D> p) {
        return "(" + to_string(p.first) + ", " + to_string(p.second) + ", " + to_string(p.third) + ", " + to_string(p.fourth) + ")";
    }

    static void debug_out(Object... args) {
        // No output as per original code
    }

    static class Pair<A, B> {
        A first;
        B second;
        Pair(A a, B b) {
            first = a;
            second = b;
        }
    }

    static class Tuple3<A, B, C> {
        A first;
        B second;
        C third;
        Tuple3(A a, B b, C c) {
            first = a;
            second = b;
            third = c;
        }
    }

    static class Tuple4<A, B, C, D> {
        A first;
        B second;
        C third;
        D fourth;
        Tuple4(A a, B b, C c, D d) {
            first = a;
            second = b;
            third = c;
            fourth = d;
        }
    }

    static <T> T mod_inv(T a, T m) {
        // Implemented for BigInteger
        BigInteger A = (BigInteger) a;
        BigInteger M = (BigInteger) m;
        return (T) (Object) A.modInverse(M);
    }

    static class Mod {
        public static class Type {
            long value;
            Type(long v) { value = v; }
        }

        long val;
        static long mod;

        public Mod() {
            this.val = 0;
        }

        public <U> Mod(U x) {
            this.val = normalize(x);
        }

        static long normalize(Object x) {
            long v;
            if (x instanceof Integer) {
                v = (Integer) x;
            } else if (x instanceof Long) {
                v = (Long) x;
            } else if (x instanceof BigInteger) {
                v = ((BigInteger) x).longValue();
            } else {
                v = 0;
            }
            v %= mod;
            if (v < 0) v += mod;
            return v;
        }

        public long get() {
            return val;
        }

        public static void setMod(long m) {
            mod = m;
        }

        public Mod add(Mod other) {
            long res = val + other.val;
            if (res >= mod) res -= mod;
            return new Mod(res);
        }

        public Mod subtract(Mod other) {
            long res = val - other.val;
            if (res < 0) res += mod;
            return new Mod(res);
        }

        public Mod multiply(Mod other) {
            long res = (val * other.val) % mod;
            return new Mod(res);
        }

        public Mod divide(Mod other) {
            return this.multiply(new Mod(mod_inv(other.val, mod)));
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Mod)) return false;
            Mod other = (Mod) o;
            return val == other.val;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        long mod_value = sc.nextLong();

        Mod.setMod(mod_value);

        List<Mod> fact = new ArrayList<>();
        List<Mod> inv_fact = new ArrayList<>();
        fact.add(new Mod(1));
        inv_fact.add(new Mod(1));

        // Function for combination
        java.util.function.BiFunction<Integer, Integer, Mod> C = (x, y) -> {
            int sz = Math.max(x, y);
            while (fact.size() <= sz) {
                int size = fact.size();
                fact.add(fact.get(size - 1).multiply(new Mod(size)));
                inv_fact.add(new Mod(mod_inv(fact.get(size).get(), Mod.mod)));
            }
            if (y < 0 || y > x) return new Mod(0);
            return fact.get(x).multiply(inv_fact.get(y)).multiply(inv_fact.get(x - y));
        };

        Mod[] ways_arr = new Mod[m + 1];
        Mod[] ways_count = new Mod[m + 1];
        for (int i = 0; i <= m; i++) {
            ways_arr[i] = new Mod(0);
            ways_count[i] = new Mod(0);
        }
        ways_count[0] = new Mod(1);

        for (int i = 1; i <= m; i++) {
            for (int j = 0; j < i; j++) {
                int l = j;
                int r = i - 1 - j;
                Mod c = C.apply(l + r, l);
                Mod add = new Mod(l + r + 2);
                ways_arr[i] = ways_arr[i].add(ways_count[l].multiply(ways_count[r]).multiply(c).multiply(add));
            }
            for (int j = 0; j < i; j++) {
                int l = j;
                int r = i - 1 - j;
                Mod add = (new Mod(l).multiply(new Mod(l + 1)).add(new Mod(r).multiply(new Mod(r + 1)))).divide(new Mod(2));
                ways_count[i] = ways_count[i].add(ways_count[l].multiply(ways_count[r]).multiply(C.apply(l + r, l)).multiply(add));
            }
        }

        Mod[][] dp = new Mod[n + 1][m + 1];
        Mod[][] ways_dp = new Mod[n + 1][m + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dp[i][j] = new Mod(0);
                ways_dp[i][j] = new Mod(0);
            }
        }
        ways_dp[0][0] = new Mod(1);

        for (int i = 1; i <= n; i++) {
            for (int s = 0; s <= Math.min(m, i); s++) {
                if (s == i) {
                    dp[i][s] = new Mod(ways_count[s].get());
                    continue;
                }
                for (int d = 1; d <= s + 1; d++) {
                    if (i - d >= 0 && s + 1 - d >= 0) {
                        Mod ft = dp[i - d][s + 1 - d];
                        Mod way = ways_dp[i - d][s + 1 - d];
                        int add = d - 1;
                        ways_dp[i][s] = ways_dp[i][s].add(way.multiply(ways_count[add]).multiply(C.apply(s, add)));
                        dp[i][s] = dp[i][s].add(way.multiply(ways_count[add]).add(ways_dp[i - d][s + 1 - d].multiply(ft)).multiply(C.apply(s, add)));
                    }
                }
            }
        }

        System.out.println(dp[n][m].get());
        sc.close();
    }
}
